 async function transition(c,req,t,action,reason=null,exception=null){let status={open:'open',suspend:'suspended',resume:'open',evaluations_close:'evaluations_closed',close:'closed',reopen:'open',archive:'archived'}[action];if(!status)S.fail('Action invalide.');let current=t.status,allowed={open:['planned'],suspend:['open','evaluations_closed'],resume:['suspended'],evaluations_close:['open'],close:['evaluations_closed','suspended','open'],reopen:['closed'],archive:['closed']}[action];if(!allowed.includes(current)||t.year_status!=='active'&&action!=='archive')S.fail('Transition impossible.',409);if(action==='open'&&t.parent_id){let p=(await c.query('SELECT status FROM academic_terms WHERE year_id=$1 AND ordinal=$2',[t.parent_id,t.ordinal])).rows[0];if(!p||!['open','evaluations_closed'].includes(p.status))S.fail('Période de référence non ouverte.',409)}if(action==='open'&&today()<t.starts_on.toISOString().slice(0,10))S.fail('Ouverture avant la date prévue.',409);if(action==='reopen'){if(!exception||new Date(exception)<=new Date()||new Date(exception)>new Date(Date.now()+7*86400000))S.fail('Réouverture limitée à sept jours.',400);if(t.parent_id){let p=(await c.query('SELECT status,exception_until FROM academic_terms WHERE year_id=$1 AND ordinal=$2',[t.parent_id,t.ordinal])).rows[0];if(p?.status==='closed'||p?.status==='archived')S.fail('Période supérieure clôturée.',409)}}if(['close','archive'].includes(action)&&(await c.query(`SELECT 1 FROM academic_years child JOIN academic_terms ct ON ct.year_id=child.id WHERE child.parent_id=$1 AND ct.ordinal=$2 AND ct.status NOT IN ('closed','archived') LIMIT 1`,[t.year_id,t.ordinal])).rowCount)S.fail('Clôturez les périodes subordonnées auparavant.',409);let next=(await c.query('UPDATE academic_terms SET status=$1,revision=revision+1,opened_at=CASE WHEN $2 IN (\'open\',\'reopen\') THEN now() ELSE opened_at END,closed_at=CASE WHEN $2=\'close\' THEN now() ELSE closed_at END,exception_until=$3,updated_at=now() WHERE id=$4 RETURNING revision',[status,action,action==='reopen'?exception:action==='resume'?t.exception_until:null,t.id])).rows[0];if(action==='close'&&t.scope==='school'){await c.query('SELECT pg_advisory_xact_lock($1::bigint)',[4800000000+Number(t.school_id)]);let locked=(await c.query("UPDATE grade_assessments SET status='locked',revision=revision+1,updated_at=now() WHERE term_id=$1 AND status='validated' RETURNING id",[t.id])).rows;for(let row of locked)await c.query("INSERT INTO grade_assessment_events(assessment_id,actor_id,action,reason,details) VALUES ($1,$2,'term_lock',$3,$4)",[row.id,req.actor.id,reason,JSON.stringify({term_revision:next.revision})])} await log(c,req,t,'term.'+action,reason,{from:current,to:status,revision:next.revision,exception_until:exception});await broadcast(c,req,{...t,revision:next.revision},action);return {status,revision:next.revision}}
 route('post','/terms/:id/action',async(req,res)=>{let n=id(req.params.id),action=choice(req.body?.action,['open','suspend','resume','evaluations_close','close','reopen','archive'],'Action'),reason=req.body?.reason?text(req.body.reason,'Justification',1000):null,exception=action==='reopen'?stamp(req.body?.exception_until,'Fin de réouverture'):null;let result=await tx(pool,async c=>{let t=await term(c,n,req.actor,true);await writeScope(c,req.actor,t,true);if(['close','reopen'].includes(action)&&!reason)S.fail('Justification obligatoire.',400);if(action==='reopen'&&req.actor.role_key==='ace_aces'||['close','archive'].includes(action)&&req.actor.role_key==='ace_aces')S.fail('Décision réservée au chef ou à la direction.',403);if(['close','reopen'].includes(action)&&t.scope==='school'){if(req.actor.role_key!=='school_head')S.fail('Proposition du chef requise.',403);let cosign=(await c.query("SELECT 1 FROM academic_delegations d JOIN accounts a ON a.id=d.ace_id WHERE d.school_id=$1 AND d.can_cosign AND d.revoked_at IS NULL AND d.role_at_grant=a.role_key AND d.organization_at_grant=a.organization_id AND a.status='active' LIMIT 1",[t.school_id])).rowCount>0;if(cosign){let x=(await c.query("INSERT INTO academic_proposals(term_id,action,proposed_by,reason,exception_until,term_revision) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id",[n,action,req.actor.id,reason,exception,t.revision])).rows[0];await log(c,req,t,'proposal.'+action,reason,{proposal_id:x.id});let people=(await c.query("SELECT d.ace_id FROM academic_delegations d JOIN accounts a ON a.id=d.ace_id WHERE d.school_id=$1 AND d.can_cosign AND d.revoked_at IS NULL AND a.status='active' AND d.role_at_grant=a.role_key AND d.organization_at_grant=a.organization_id",[t.school_id])).rows;for(let p of people)await notify(c,p.ace_id,'new','academic_term',n,'academic:proposal:'+x.id,'Visa ACE/ACES requis : '+action);return {proposal_id:x.id,pending:true}}}return transition(c,req,t,action,reason,exception)});res.json(result)});
 route('post','/proposals/:id/review',async(req,res)=>{let n=id(req.params.id),decision=choice(req.body?.decision,['approved','rejected'],'Décision'),out=await tx(pool,async c=>{let p=(await c.query('SELECT * FROM academic_proposals WHERE id=$1 FOR UPDATE',[n])).rows[0];if(!p||p.status!=='pending')S.fail('Proposition introuvable.',404);let t=await term(c,Number(p.term_id),req.actor,true),d=await delegation(c,req.actor,t.school_id);if(req.actor.role_key!=='ace_aces'||!d?.can_cosign||String(req.actor.id)===String(p.proposed_by)||t.revision!==p.term_revision)S.fail('Cosignature interdite ou proposition périmée.',403);await c.query('UPDATE academic_proposals SET status=$1,signed_by=$2,reviewed_at=now() WHERE id=$3',[decision,req.actor.id,n]);await log(c,req,t,'proposal.'+decision,decision==='rejected'?text(req.body?.reason,'Motif',1000):p.reason,{proposal_id:n});if(decision==='rejected')return {status:'rejected'};let result=await transition(c,req,t,p.action,p.reason,p.exception_until);return {status:'approved',...result}});res.json(out)});
 const followKey=t=>'academic:'+t.id+':'+t.revision+':%';
 async function termRecipients(c,t){return (await c.query(`SELECT n.user_id,a.full_name,count(*)::int sent,max(n.created_at) last_sent FROM activity_notifications n JOIN accounts a ON a.id=n.user_id WHERE n.entity_type='academic_term' AND n.entity_id=$1 AND n.event_key LIKE $2 GROUP BY n.user_id,a.full_name ORDER BY a.full_name,n.user_id LIMIT 5000`,[t.id,followKey(t)])).rows}
