 route('post','/terms/:id/ack',async(req,res)=>{let t=await term(pool,id(req.params.id),req.actor);let r=await tx(pool,async c=>{let x=await c.query("SELECT 1 FROM activity_notifications WHERE entity_type='academic_term' AND entity_id=$1 AND user_id=$2 AND event_key LIKE $3 LIMIT 1",[t.id,req.actor.id,followKey(t)]);if(!x.rowCount)S.fail('Aucune notification à accuser.',403);let result=await c.query('INSERT INTO academic_term_acks(term_id,revision,account_id) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING RETURNING acknowledged_at',[t.id,t.revision,req.actor.id]);if(result.rowCount)await log(c,req,t,'term.ack',null,{revision:t.revision});return {acknowledged:true,new_ack:!!result.rowCount}});res.json(r)});
 route('get','/terms/:id/followup',async(req,res)=>{let t=await term(pool,id(req.params.id),req.actor),recipients=await termRecipients(pool,t),ids=recipients.map(x=>Number(x.user_id)),views=(await pool.query('SELECT account_id,count(*)::int n FROM academic_term_views WHERE term_id=$1 AND revision=$2 AND account_id=ANY($3::bigint[]) GROUP BY account_id',[t.id,t.revision,ids])).rows,acks=(await pool.query('SELECT account_id,acknowledged_at FROM academic_term_acks WHERE term_id=$1 AND revision=$2 AND account_id=ANY($3::bigint[])',[t.id,t.revision,ids])).rows,v=new Map(views.map(x=>[String(x.account_id),x.n])),ack=new Map(acks.map(x=>[String(x.account_id),x.acknowledged_at])),isManager=req.actor.role_key==='platform_admin'||req.actor.role_key==='regional_director'&&String(req.actor.region_id)===String(t.region_id)||req.actor.role_key==='school_head'&&String(req.actor.organization_id)===String(t.school_id)||req.actor.role_key==='ace_aces'&&t.scope==='school'&&!!(await delegation(pool,req.actor,t.school_id))?.can_manage;let result=recipients.map(x=>({account_id:x.user_id,full_name:x.full_name,sent:x.sent,views:v.get(String(x.user_id))||0,acknowledged_at:ack.get(String(x.user_id))||null}));res.json({revision:t.revision,summary:isManager?{sent:recipients.reduce((n,x)=>n+x.sent,0),recipients:recipients.length,readers:result.filter(x=>x.views>0).length,views:result.reduce((n,x)=>n+x.views,0),acknowledged:result.filter(x=>x.acknowledged_at).length}:null,mine:result.find(x=>String(x.account_id)===String(req.actor.id))||null,recipients:isManager?result:[]})});
 route('post','/terms/:id/remind',async(req,res)=>{let mode=choice(req.body?.mode,['unviewed','unacknowledged'],'Relance'),out=await tx(pool,async c=>{let t=await term(c,id(req.params.id),req.actor,true);await writeScope(c,req.actor,t,true);let people=await termRecipients(c,t),count=0;for(let p of people){if(String(p.user_id)===String(req.actor.id))continue;let seen=(await c.query('SELECT 1 FROM academic_term_views WHERE term_id=$1 AND revision=$2 AND account_id=$3 LIMIT 1',[t.id,t.revision,p.user_id])).rowCount,acked=(await c.query('SELECT 1 FROM academic_term_acks WHERE term_id=$1 AND revision=$2 AND account_id=$3 LIMIT 1',[t.id,t.revision,p.user_id])).rowCount;if(mode==='unviewed'&&seen||mode==='unacknowledged'&&acked)continue;let x=await c.query('SELECT 1 FROM activity_notifications WHERE user_id=$1 AND event_key=$2',[p.user_id,'academic:remind:'+t.id+':'+t.revision+':'+mode]);if(x.rowCount)continue;await notify(c,p.user_id,'reminder','academic_term',t.id,'academic:remind:'+t.id+':'+t.revision+':'+mode,'Rappel de période : '+t.name);count++}await log(c,req,t,'term.remind',mode,{count,revision:t.revision});return {notified:count}});res.json(out)});
 route('get','/terms/:id',async(req,res)=>{let t=await term(pool,id(req.params.id),req.actor),history=(await pool.query('SELECT action,reason,details,created_at,actor_id FROM academic_actions WHERE term_id=$1 ORDER BY id DESC LIMIT 100',[t.id])).rows,proposals=(await pool.query('SELECT id,action,reason,status,created_at FROM academic_proposals WHERE term_id=$1 ORDER BY id DESC LIMIT 20',[t.id])).rows;res.json({term:t,history,proposals})});
 // Les routes des classes, activités pédagogiques, notes et calendriers suivent ci-dessous.
 async function schoolManager(c,a,school){if(a.role_key==='school_head'&&String(a.organization_id)===String(school))return true;return !!(await delegation(c,a,school))?.can_manage}
 async function klass(c,n,a,write=false){let r=(await c.query('SELECT cl.*,y.region_id,y.scope,y.status year_status FROM academic_classes cl JOIN academic_years y ON y.id=cl.year_id WHERE cl.id=$1',[n])).rows[0];if(!r||!visible({...r,scope:'school'},a)||a.role_key==='ace_aces'&&!await delegation(c,a,r.school_id))S.fail('Classe inaccessible.',404);if(write&&!await schoolManager(c,a,r.school_id))S.fail('Gestion de classe non autorisée.',403);if(a.role_key==='teacher'&&!await c.query('SELECT 1 FROM academic_assignments WHERE class_id=$1 AND teacher_id=$2',[n,a.id]).then(x=>x.rowCount>0))S.fail('Classe non attribuée.',404);return r}
 async function assignment(c,n,a,write=false){let r=(await c.query('SELECT at.*,cl.school_id,cl.year_id,y.region_id,y.status year_status FROM academic_assignments at JOIN academic_classes cl ON cl.id=at.class_id JOIN academic_years y ON y.id=cl.year_id WHERE at.id=$1',[n])).rows[0];if(!r||!visible({...r,scope:'school'},a)||a.role_key==='ace_aces'&&!await delegation(c,a,r.school_id))S.fail('Affectation inaccessible.',404);if(write&&String(r.teacher_id)!==String(a.id))S.fail('Cette discipline ne vous est pas affectée.',403);return r}
 const termAssignment=(t,at)=>{if(String(t.year_id)!==String(at.year_id)||String(t.school_id)!==String(at.school_id))S.fail('Affectation hors du trimestre.',403)};
 function openTerm(t){if(t.year_status!=='active'||!['open','evaluations_closed'].includes(t.status))S.fail('Période indisponible.',409)}
 function assessWindow(t){openTerm(t);if(t.status!=='open'||today()<(t.evaluation_opens_on||t.starts_on).toISOString().slice(0,10)||today()>(t.evaluation_closes_on||t.ends_on).toISOString().slice(0,10))S.fail('Création des évaluations clôturée.',409)}
 function notesWindow(t){openTerm(t);if(today()<(t.evaluation_opens_on||t.starts_on).toISOString().slice(0,10)||today()>(t.notes_deadline_on||t.ends_on).toISOString().slice(0,10)&&!(t.exception_until&&new Date(t.exception_until)>new Date()))S.fail('Saisie des notes clôturée.',409)}
 route('post','/years/:id/classes',async(req,res)=>{let n=id(req.params.id),name=text(req.body?.name,'Classe',100),out=await tx(pool,async c=>{let y=await year(c,n,req.actor,true);if(y.scope!=='school'||!await schoolManager(c,req.actor,y.school_id)||!['planned','active'].includes(y.status))S.fail('Création de classe interdite.',403);let x=(await c.query('INSERT INTO academic_classes(year_id,school_id,name,created_by) VALUES ($1,$2,$3,$4) RETURNING id',[n,y.school_id,name,req.actor.id])).rows[0];await log(c,req,y,'class.create',null,{class_id:x.id,name});return x});res.status(201).json(out)});
 route('get','/years/:id/classes',async(req,res)=>{let y=await year(pool,id(req.params.id),req.actor),rows=(await pool.query(`SELECT cl.id,cl.name,cl.school_id,o.name school_name,(SELECT count(*)::int FROM academic_pupils p WHERE p.class_id=cl.id) pupils FROM academic_classes cl JOIN organizations o ON o.id=cl.school_id WHERE cl.year_id IN (SELECT z.id FROM academic_years z WHERE z.scope='school' AND z.label=$2 AND ($3::bigint IS NULL OR z.region_id=$3)) AND ($1::bigint IS NULL OR cl.school_id=$1) ORDER BY cl.school_id,cl.name`,[y.scope==='school'?y.school_id:null,y.label,y.scope==='region'?y.region_id:null])).rows;if(req.actor.role_key==='teacher'){let mine=(await pool.query('SELECT class_id FROM academic_assignments WHERE teacher_id=$1',[req.actor.id])).rows.map(x=>String(x.class_id));return res.json({items:rows.filter(x=>mine.includes(String(x.id)))})}res.json({items:rows})});
 route('post','/classes/:id/pupils',async(req,res)=>{let n=id(req.params.id),name=text(req.body?.full_name,'Nom élève',160),code=req.body?.registration_code?text(req.body.registration_code,'Matricule',80):null,out=await tx(pool,async c=>{let cl=await klass(c,n,req.actor,true);if(!['active','planned'].includes(cl.year_status))S.fail('Année close.',409);let x=(await c.query('INSERT INTO academic_pupils(class_id,full_name,registration_code,created_by) VALUES ($1,$2,$3,$4) RETURNING id',[n,name,code,req.actor.id])).rows[0];await audit(c,req,'academic.pupil.create','academic_pupil',x.id,cl.region_id,{class_id:n});return x});res.status(201).json(out)});
