 route('post','/classes/:id/assignments',async(req,res)=>{let n=id(req.params.id),uid=id(req.body?.teacher_id),subject=req.body?.subject_id?null:text(req.body?.subject,'Discipline',100),out=await tx(pool,async c=>{let cl=await klass(c,n,req.actor,true),person=(await c.query('SELECT id,role_key,status,organization_id FROM accounts WHERE id=$1',[uid])).rows[0];if(!person||person.status!=='active'||person.role_key!=='teacher'||String(person.organization_id)!==String(cl.school_id)||!['active','planned'].includes(cl.year_status))S.fail('Enseignant non autorisé.',403);let chosen=req.body?.subject_id?(await c.query('SELECT id,name FROM catalog_subjects WHERE id=$1 AND active',[id(req.body.subject_id)])).rows[0]:(await c.query('SELECT id,name FROM catalog_subjects WHERE lower(btrim(name))=lower(btrim($1)) AND active',[subject])).rows[0];if(!chosen)S.fail('Matière absente du catalogue commun : demander son ajout à l’administration générale.',400);if(req.body?.subject_id&&!(await c.query('SELECT 1 FROM academic_class_subjects WHERE class_id=$1 AND subject_id=$2',[n,chosen.id])).rowCount)S.fail('Associez d’abord cette matière à la classe et au programme local.',409);await c.query('INSERT INTO academic_class_subjects(class_id,subject_id,added_by) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[n,chosen.id,req.actor.id]);let x=(await c.query('INSERT INTO academic_assignments(class_id,teacher_id,subject,subject_id,created_by) VALUES ($1,$2,$3,$4,$5) RETURNING id',[n,uid,chosen.name,chosen.id,req.actor.id])).rows[0];await audit(c,req,'academic.assignment','academic_assignment',x.id,cl.region_id,{class_id:n,teacher_id:uid,subject});return x});res.status(201).json(out)});
 route('get','/classes/:id/assignments',async(req,res)=>{let cl=await klass(pool,id(req.params.id),req.actor);let x=(await pool.query('SELECT a.id,a.teacher_id,t.full_name teacher_name,a.subject FROM academic_assignments a JOIN accounts t ON t.id=a.teacher_id WHERE a.class_id=$1 ORDER BY a.subject',[cl.id])).rows;res.json({items:x})});
 route('post','/terms/:id/assessments',async(req,res)=>{let n=id(req.params.id),assignmentId=id(req.body?.assignment_id),kind=choice(req.body?.kind,['homework','composition'],'Type'),evalType=req.body?.evaluation_type_id?id(req.body.evaluation_type_id):null,title=text(req.body?.title,'Devoir',180),occurs=stamp(req.body?.occurs_at,'Date du devoir'),coef=Number(req.body?.coefficient||1);if(!Number.isFinite(coef)||coef<=0||coef>20)S.fail('Coefficient invalide.');let result=await tx(pool,async c=>{let t=await term(c,n,req.actor,true),at=await assignment(c,assignmentId,req.actor,true);termAssignment(t,at);assessWindow(t);if(evalType&&!(await c.query('SELECT 1 FROM catalog_evaluation_types WHERE id=$1 AND active',[evalType])).rowCount)S.fail('Type d’évaluation désactivé.',409);let d=occurs.slice(0,10);if(d<(t.evaluation_opens_on||t.starts_on).toISOString().slice(0,10)||d>(t.evaluation_closes_on||t.ends_on).toISOString().slice(0,10))S.fail('Devoir hors de la fenêtre des évaluations.',409);let x=(await c.query('INSERT INTO academic_assessments(term_id,assignment_id,kind,title,occurs_at,coefficient,created_by,evaluation_type_id) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id',[n,assignmentId,kind,title,occurs,coef,req.actor.id,evalType])).rows[0];await log(c,req,t,'assessment.create',null,{assessment_id:x.id,kind,assignment_id:assignmentId});return x});res.status(201).json(result)});
